from pathlib import Path
Path('operations.py').write_text(""""Read-only diagnostics and accepted-outcome accounting for OPS-G4/v2."""

from collections.abc import Mapping
from contextlib import closing
from decimal import (
    Context, Decimal, InvalidOperation, MAX_EMAX, MIN_EMIN, ROUND_HALF_EVEN,
    localcontext,
)
import hashlib
import os
from pathlib import Path
import re
import sqlite3
import stat
from tempfile import TemporaryDirectory


_REFERENCE = (
    "id", "asset_id", "member_id", "starts_at", "ends_at", "request_key",
    "request_hash", "state", "version",
)
_RECORDED = (
    "reservation_id", "trusted_member_id", "asset_id", "starts_at", "ends_at",
    "idempotency_key", "payload_fingerprint", "state", "version",
)
_CURRENT = {
    "reservations": (_REFERENCE, "id"),
    "reservations_v2": (_RECORDED, "reservation_id"),
}
_OLD_COLUMNAR = (
    "id", "member_id", "asset_id", "starts_at", "ends_at", "request_key",
)
_OLD_PUBLIC = _RECORDED[:6]
_HISTORY = {
    "reservations": {_OLD_COLUMNAR, _OLD_PUBLIC, _REFERENCE[:7]},
    "archived_g1_reservations": {_OLD_COLUMNAR},
    "bookings_v2": {("booking_no", "payload")},
}
_DECIMAL_TEXT = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?"
)


def _changed():
    return RuntimeError("storage changed during diagnosis; stable observation unavailable")


def _stamp(info):
    return (
        info.st_dev, info.st_ino, info.st_mode, info.st_size,
        info.st_mtime_ns, info.st_ctime_ns,
    )


def _capture_file(path, *, required=False):
    try:
        stream = path.open("rb")
    except FileNotFoundError:
        if required:
            raise
        return None
    with stream:
        before = os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode):
            raise ValueError("diagnosis requires regular storage files")
        data = stream.read()
        after = os.fstat(stream.fileno())
    try:
        current = path.stat()
    except OSError as error:
        raise _changed() from error
    if _stamp(before) != _stamp(after) or _stamp(after) != _stamp(current):
        raise _changed()
    return data, _stamp(after), hashlib.sha256(data).hexdigest()


def _capture_storage(path):
    # WAL carries committed data; SHM/journal changes also invalidate stability.
    return {
        "database": _capture_file(path, required=True),
        **{suffix: _capture_file(Path(str(path) + suffix))
           for suffix in ("-wal", "-shm", "-journal")},
    }


def _current_mapping(connection):
    version = connection.execute("PRAGMA user_version").fetchone()[0]
    if version != 3:
        raise ValueError("unsupported schema version; owner mapping required")
    objects = connection.execute(
        "SELECT type, name FROM sqlite_master WHERE name NOT GLOB 'sqlite_*'"
    ).fetchall()
    if any(kind not in ("table", "index") for kind, _ in objects):
        raise ValueError("unsupported schema objects; owner mapping required")
    choices = []
    for kind, table in objects:
        if kind != "table":
            continue
        if table not in _CURRENT and table not in _HISTORY:
            raise ValueError("unrecognized table; owner mapping required")
        # Only the literal allowlisted table names above reach this statement.
        columns = connection.execute(f'PRAGMA table_xinfo("{table}")').fetchall()
        signature = tuple(row[1] for row in columns)
        if any(row[6] for row in columns):
            raise ValueError("unsupported hidden/generated columns; owner mapping required")
        if table in _CURRENT and signature == _CURRENT[table][0]:
            choices.append((table, _CURRENT[table][1]))
        elif signature not in _HISTORY.get(table, set()):
            raise ValueError("unsupported column signature; owner mapping required")
    if len(choices) != 1:
        raise ValueError("missing or competing current representations; owner mapping required")
    return version, *choices[0]


def _diagnose_copy(snapshot):
    # Never connect SQLite to the source: a read-only WAL connection can still
    # create or update source shared-memory files. Only this disposable image
    # can acquire SQLite sidecars. No source is restored, repaired, or initialized.
    with TemporaryDirectory(prefix="reservation-diagnosis-") as directory:
        image = Path(directory) / "observation.sqlite"
        image.write_bytes(snapshot["database"][0])
        for suffix in ("-wal", "-journal"):
            if snapshot[suffix] is not None:
                Path(str(image) + suffix).write_bytes(snapshot[suffix][0])
        with closing(sqlite3.connect(image.as_uri() + "?mode=ro", uri=True)) as connection:
            connection.execute("PRAGMA query_only = ON")
            connection.execute("BEGIN")
            version, table, identifier = _current_mapping(connection)
            counts = dict(connection.execute(
                f'SELECT state, COUNT(*) FROM "{table}" GROUP BY state ORDER BY state'
            ))
            pairs = [list(row) for row in connection.execute(f"""
                SELECT a.{identifier}, b.{identifier}
                FROM "{table}" AS a JOIN "{table}" AS b
                  ON a.{identifier} < b.{identifier}
                 AND a.asset_id = b.asset_id
                 AND a.starts_at < b.ends_at
                 AND b.starts_at < a.ends_at
                WHERE a.state = 'active' AND b.state = 'active'
                ORDER BY a.{identifier}, b.{identifier}
            """)]
    return {
        "schema_version": version,
        "reservation_table": table,
        "counts": counts,
        "active_overlap_pairs": pairs,
        "diagnosis": "ACTIVE_OVERLAP" if pairs else "NO_ACTIVE_OVERLAP_OBSERVED",
    }


def diagnose(path):
    """Observe one authorized schema-3 image without writing source storage.

    Changes to bytes, file identity, timestamps, or sidecar presence invalidate
    the observation. This is bounded overlap diagnosis, not an integrity
    certificate or authority to repair. SQLite errors propagate on corrupt or
    unrecoverable copied storage.
    """
    resolved = Path(path).resolve(strict=True)
    before = _capture_storage(resolved)
    try:
        result = _diagnose_copy(before)
    finally:
        try:
            after = _capture_storage(resolved)
        except OSError as error:
            raise _changed() from error
        if before != after:
            raise _changed()
    result.update({
        "path": str(resolved),
        "sha256": before["database"][2],
        "bytes_unchanged": True,
        "observed_files": {
            name: {
                "before_sha256": original[2],
                "after_sha256": after[name][2],
            }
            for name, original in before.items() if original is not None
        },
    })
    return result


def _amount(value, field):
    if isinstance(value, bool) or not isinstance(value, (str, int, float, Decimal)):
        raise ValueError(f"{field} must be a finite nonnegative decimal value")
    try:
        if isinstance(value, Decimal):
            number = value
        else:
            text = str(value).strip()
            if not _DECIMAL_TEXT.fullmatch(text):
                raise ValueError(f"{field} is not numeric")
            number = Decimal(text)
    except (InvalidOperation, TypeError, ValueError) as error:
        raise ValueError(f"{field} is not numeric") from error
    if not number.is_finite() or number < 0:
        raise ValueError(f"{field} must be finite and nonnegative")
    return number


def _context(precision):
    return Context(
        prec=max(28, precision), rounding=ROUND_HALF_EVEN,
        Emax=MAX_EMAX, Emin=MIN_EMIN,
    )


def _total(values):
    if not values:
        return Decimal(0)
    lowest = min(value.as_tuple().exponent for value in values)
    highest = max(value.adjusted() for value in values)
    # Enough significant digits for exact addition, including carry digits.
    precision = highest - lowest + 1 + len(str(len(values)))
    with localcontext(_context(precision)):
        total = values[0]
        for value in values[1:]:
            total += value
    return total


def _per_accepted(total, accepted):
    # Keep totals exact; repeating quotients use at least 28 significant digits.
    with localcontext(_context(len(total.as_tuple().digits))):
        return str(total / Decimal(accepted))


def cost_summary(attempts, accepted):
    """Include every attempt; use only the separately supplied outcome count."""
    if type(accepted) is not int or accepted < 0:
        raise ValueError("accepted must be a nonnegative integer")
    try:
        iterator = iter(attempts)
    except TypeError as error:
        raise ValueError("attempts must be an iterable of accounting records") from error
    costs, minutes = [], []
    for attempt in iterator:
        if not isinstance(attempt, Mapping) or not {"cost_eur", "minutes"} <= attempt.keys():
            raise ValueError("each attempt must supply cost_eur and minutes")
        costs.append(_amount(attempt["cost_eur"], "cost_eur"))
        minutes.append(_amount(attempt["minutes"], "minutes"))
    cost, time = _total(costs), _total(minutes)
    return {
        "attempts": len(costs),
        "accepted": accepted,
        "total_cost_eur": str(cost),
        "total_minutes": str(time),
        "cost_per_accepted_eur": _per_accepted(cost, accepted) if accepted else None,
        "minutes_per_accepted": _per_accepted(time, accepted) if accepted else None,
        "status": "OK" if accepted else "NO_ACCEPTED_OUTCOME",
    }
